"// SPDX-License-Identifier: MIT

/**
 * @title  Proxy
 * @notice The Freeport's address on STRATO: state lives here, code runs from
 *         `logicContract` by delegatecall, and the owner can point it at new
 *         code without moving anything. The same shape as strato-platform's
 *         `Proxy` (which AdminRegistry, MercataBridge and CDPVault use on
 *         mainnet), without its AdminRegistry voting fallback. The NAME is
 *         load-bearing: bloc builds calls to a contract named exactly \"Proxy\"
 *         against the ABI of its `logicContract`, and the VM registers a
 *         \"Proxy\" whose first constructor argument is an address under the
 *         logic's Cirrus tables. Any other name, and bloc refuses every
 *         method the proxy does not declare itself.
 * @dev    SolidVM keys storage by variable name, so `owner` here IS the
 *         Freeport's `owner`: one key sets remotes and swaps code. The logic
 *         contract takes no constructor arguments; `initialize` is called on
 *         this address once, by the owner, right after creation. The VM
 *         refuses `<constructor>` calls on a deployed contract (strato-platform
 *         PR #7618, 2026-10-24), so initialization cannot be replayed through
 *         the fallback.
 */
contract record Proxy {
    address public logicContract;
    address public owner;

    event LogicSet(address logicContract);

    constructor(address logic_, address owner_) {
        require(logic_ != address(0), \"Proxy: zero logic\");
        require(owner_ != address(0), \"Proxy: zero owner\");
        logicContract = logic_;
        owner = owner_;
        emit LogicSet(logic_);
    }

    /// @notice Point this address at new code. State stays; see Freeport.sol's
    ///         header for what a new version may and may not change.
    function setLogicContract(address logic_) external {
        require(msg.sender == owner, \"Proxy: not owner\");
        require(logic_ != address(0), \"Proxy: zero logic\");
        logicContract = logic_;
        emit LogicSet(logic_);
    }

    fallback(variadic args) external returns (variadic) {
        return logicContract.delegatecall(msg.sig, args);
    }
}
