// One-off logic for the Escrow proxy. While installed it can only return open
// deposits to their senders, so no deposit or redemption can happen during the
// refund. Afterwards the proxy is pointed at the patched Escrow.
contract record EscrowRefund is Ownable {
  struct Deposit {
    address sender;
    uint quantity;
    address[] tokens;
    uint[] amounts;
    uint expiry;
  }

  mapping(address => Deposit) public record deposits;

  event Cancelled(address indexed ephemeralAddress, address[] indexed tokens, uint256[] amounts, address sender);

  constructor(address _initialOwner) Ownable(_initialOwner) { }

  // Refunds every redemption left, closed the way Escrow closes a deposit.
  // Addresses with nothing left are skipped, so a batch can be rerun.
  function refundAll(address[] ephemeralAddresses) external onlyOwner {
    for (uint k = 0; k < ephemeralAddresses.length; k++) {
      address ephemeralAddress = ephemeralAddresses[k];
      Deposit storage d = deposits[ephemeralAddress];
      if (d.quantity > 0) {
        address sender = d.sender;
        address[] tokens = [];
        uint[] amounts = [];
        for (uint i = 0; i < d.tokens.length; i++) {
          tokens.push(d.tokens[i]);
          amounts.push(d.quantity * d.amounts[i]);
          d.tokens[i] = address(0);
          d.amounts[i] = 0;
        }
        d.tokens.length = 0;
        d.amounts.length = 0;
        d.expiry = 0;
        d.quantity = 0;

        for (uint j = 0; j < tokens.length; j++) {
          require(IERC20(tokens[j]).transfer(sender, amounts[j]), "transfer failed");
        }

        emit Cancelled(ephemeralAddress, tokens, amounts, sender);
      }
    }
  }
}

